package android.accessibilityservice;import android.hardware.HardwareBuffer;import android.graphics.ColorSpace;public class AccessibilityService{public static final int ERROR_TAKE_SCREENSHOT_INTERVAL_TIME_SHORT=3;public interface TakeScreenshotCallback{void onSuccess(ScreenshotResult r);void onFailure(int e);}public static class ScreenshotResult{private final HardwareBuffer b;public ScreenshotResult(){b=new HardwareBuffer();}public ScreenshotResult(int w,int h){b=new HardwareBuffer(w,h);}public HardwareBuffer getHardwareBuffer(){return b;}public ColorSpace getColorSpace(){return new ColorSpace();}}}
